`),l(576,"span",7),u(577,"        remove"),d(),u(578," "),l(579,"span",7),u(580,"dead"),d(),l(581,"span",11),u(582,"-"),d(),l(583,"span",7),u(584,"ends"),d(),l(585,"span",8),u(586,"("),d(),l(587,"span",7),u(588,"newly"),d(),u(589," "),l(590,"span",7),u(591,"created"),d(),u(592," "),l(593,"span",7),u(594,"sinks"),d(),u(595," "),l(596,"span",12),u(597,"\u2260"),d(),u(598," "),l(599,"span",8),u(600,"("),d(),l(601,"span",7),u(602,"t"),d(),l(603,"span",8),u(604,"))"),d(),u(605,`
